    next if line =~ /^\s*<%#/
    hits = []
    ATTRS.each do |attr|
      line.scan(/#{attr}="([^"]*)"/) { |m| hits << m[0] }
      line.scan(/#{attr}:\s*"([^"]*)"/) { |m| hits << m[0] }
    end
    line.scan(/>([^<>]+)</) { |m| hits << m[0] }
    line.scan(/"([^"]*)"/).each { |m| hits << m[0] }
    hits.map!(&:strip).reject! { |s| s.empty? || s !~ /[A-Za-z]{2}/ }
    .reject! { |s| s =~ /\A[a-z0-9_\-\.\/\s]+\z/ }
    .reject! { |s| s =~ /->|controller|target|class|icon|https?:|\.svg|\.png|rel=|data-|script_name|format:/ }
    hits.uniq.each { |h| puts "#{f.sub('/app/app/views/','')}:#{i+1}: #{h.inspect}" }
  end
end
