def deep_merge(target, other)
  other.each { |k, v| v.is_a?(Hash) && target[k].is_a?(Hash) ? deep_merge(target[k], v) : target[k] = v }
  target
end

{ "en" => EN, "ja" => JA }.each do |locale, data|
  file = "/app/config/locales/#{locale}.yml"
  tree = YAML.load_file(file)
  deep_merge(tree[locale], data)
  File.write(file, tree.to_yaml.sub(/\A---\n/, ""))
end
